@Override public InputStream read(final Path file, final TransferStatus status, final ConnectionCallback connectionCallback) throws BackgroundException {
    final MantaHttpHeaders headers = new MantaHttpHeaders();
    try {
        if (status.isAppend()) {
            final HttpRange range = HttpRange.withStatus(status);
            headers.setByteRange(range.getStart(), range.getEnd() < 0 ? null : range.getEnd());
        }
        return session.getClient().getAsInputStream(file.getAbsolute(), headers);
    } catch (UnsupportedOperationException e) {
        try {
            return emptyFileFallback(file);
        } catch (AccessDeniedException e1) {
            throw new BackgroundException("Access denied while reading file: " + file, e1);
        } catch (IllegalFormatException e2) {
            throw new BackgroundException("Invalid format while processing file: " + file, e2);
        }
    } catch (IOException e) {
        throw new MantaExceptionMappingService(session).map(e);
    }
}
